"""Generate the raw kernel payload union carried by marimo/kernelNotification."""

from __future__ import annotations

import json
import types
import typing

import msgspec
from marimo._ast.cell import CellConfig
from marimo._messaging import notification
from marimo._messaging.cell_output import CellOutput
from marimo._types.ids import CellId_t

from scripts.codegen.output import EXTENSION

OUTPUT = EXTENSION / "src" / "schemas" / "KernelNotificationPayload.gen.ts"
LABEL = "Kernel notification payloads"

HEADER = """\
// AUTO-GENERATED FILE — DO NOT EDIT.
// Raw marimo kernel notifications, generated by `just codegen` from
// marimo._messaging.notification.NotificationMessage.
import type { components } from "@marimo-team/openapi/src/api";

type Schemas = components["schemas"];
"""

_TS_TYPES: dict[object, str] = {
    str: "string",
    bool: "boolean",
    int: "number",
    float: "number",
    type(None): "null",
    CellId_t: 'Schemas["CellId"]',
    CellConfig: 'Schemas["CellConfig"]',
    CellOutput: 'Schemas["CellOutput"]',
}


def _editor_tags() -> set[str]:
    editor = getattr(notification, "EditorNotification", None)
    if editor is not None:
        return {cls.name for cls in typing.get_args(editor)}
    # The 0.25.2 pin predates the editor/kernel split and still has reconnected.
    return {cls.name for cls in typing.get_args(notification.NotificationMessage)} - {
        "cell-op",
        "execution",
        "interrupted",
        "notebook-document-transaction",
        "reconnected",
    }


class _WireTypes:
    def __init__(self) -> None:
        self.definitions: dict[str, str] = {}

    def field_type(self, annotation: object) -> str:  # noqa: PLR0911
        if annotation in _TS_TYPES:
            return _TS_TYPES[annotation]
        origin = typing.get_origin(annotation)
        args = typing.get_args(annotation)
        if isinstance(annotation, typing.NewType):
            return self.field_type(annotation.__supertype__)
        if origin is typing.Annotated:
            return self.field_type(args[0])
        if origin in (types.UnionType, typing.Union):
            # msgspec encodes UNSET as an absent property.
            return " | ".join(
                self.field_type(t) for t in args if t is not msgspec.UnsetType
            )
        if origin is typing.Literal:
            return " | ".join(json.dumps(value) for value in args)
        if origin is list or (origin is tuple and args[1:] == (Ellipsis,)):
            return f"Array<{self.field_type(args[0])}>"
        if origin is dict:
            return f"Record<{self.field_type(args[0])}, {self.field_type(args[1])}>"
        if isinstance(annotation, type) and issubclass(annotation, msgspec.Struct):
            return self.struct_type(annotation)
        msg = f"unsupported kernel notification field type: {annotation!r}"
        raise TypeError(msg)

    def struct_type(self, cls: type[msgspec.Struct]) -> str:
        name = cls.__name__
        if name in self.definitions:
            return name
        config = cls.__struct_config__
        fields = []
        if config.tag is not None:
            fields.append(f"  {config.tag_field}: {json.dumps(config.tag)};")
        for field in msgspec.structs.fields(cls):
            key = field.encode_name + ("" if field.required else "?")
            fields.append(f"  {key}: {self.field_type(field.type)};")
        self.definitions[name] = f"type {name} = {{\n" + "\n".join(fields) + "\n};"
        return name


def generate() -> str:
    wire = _WireTypes()
    editor_tags = _editor_tags()
    members = [
        f'Schemas["{cls.__name__}"]'
        if cls.name in editor_tags
        else wire.struct_type(cls)
        for cls in typing.get_args(notification.NotificationMessage)
    ]
    union = "export type KernelNotificationPayload =\n  | " + "\n  | ".join(members)
    return "\n\n".join([HEADER.rstrip(), *wire.definitions.values(), union + ";\n"])
